import json
from typing import Optional
import httpx
from fastmcp import Server
from fastmcp.types import TextContent


def create_openapi_mcp_server(
    spec: dict,
    client: httpx.AsyncClient,
    server_name: str = "openapi-mcp"
) -> Server:
    """
    Create an MCP server from an OpenAPI 3.0 specification.

    Args:
        spec: OpenAPI 3.0 specification as a Python dict
        client: httpx.AsyncClient configured with base URL
        server_name: Name for the MCP server

    Returns:
        Configured Server instance ready to handle tool calls
    """
    server = Server(server_name)
    tool_handlers = {}

    paths = spec.get("paths", {})

    for path, path_item in paths.items():
        for method_str, operation in path_item.items():
            method = method_str.lower()
            if method not in ["get", "post", "put", "patch", "delete", "head", "options"]:
                continue

            operation_id = operation.get("operationId")
            summary = operation.get("summary", "")
            description = operation.get("description", "")

            tool_name = operation_id or f"{method}_{path.replace('/', '_').replace('{', '').replace('}', '')}"
            tool_description = summary or description or f"{method.upper()} {path}"

            params_info = {}
            input_properties = {}
            required_params = []

            for param in operation.get("parameters", []):
                param_name = param.get("name")
                param_in = param.get("in")
                param_schema = param.get("schema", {"type": "string"})
                is_required = param.get("required", False)

                params_info[param_name] = {
                    "in": param_in,
                    "required": is_required
                }
                input_properties[param_name] = param_schema
                if is_required:
                    required_params.append(param_name)

            request_body = operation.get("requestBody", {})
            if request_body:
                content = request_body.get("content", {})
                if "application/json" in content:
                    body_schema = content["application/json"].get("schema", {"type": "object"})
                    input_properties["body"] = body_schema
                    if request_body.get("required", False):
                        required_params.append("body")

            input_schema = {
                "type": "object",
                "properties": input_properties
            }
            if required_params:
                input_schema["required"] = required_params

            def make_handler(path: str, method: str, params_info: dict):
                async def handler(**kwargs) -> TextContent:
                    url = path
                    query_params = {}
                    headers = {}
                    body = None

                    for key, value in kwargs.items():
                        if key in params_info:
                            param_location = params_info[key]["in"]
                            if param_location == "path":
                                url = url.replace(f"{{{key}}}", str(value))
                            elif param_location == "query":
                                query_params[key] = value
                            elif param_location == "header":
                                headers[key] = value
                        elif key == "body":
                            body = value

                    try:
                        response = await client.request(
                            method.upper(),
                            url,
                            params=query_params if query_params else None,
                            headers=headers if headers else None,
                            json=body if isinstance(body, dict) else None,
                            content=body if isinstance(body, str) else None
                        )

                        content_type = response.headers.get("content-type", "")
                        if "application/json" in content_type:
                            response_body = response.json()
                        else:
                            response_body = response.text

                        result = {
                            "status": response.status_code,
                            "body": response_body
                        }
                        return TextContent(type="text", text=json.dumps(result, indent=2))
                    except Exception as e:
                        error_result = {
                            "error": str(e),
                            "error_type": type(e).__name__
                        }
                        return TextContent(type="text", text=json.dumps(error_result, indent=2))

                return handler

            handler = make_handler(path, method_str, params_info)
            tool_handlers[tool_name] = {
                "handler": handler,
                "description": tool_description,
                "schema": input_schema
            }

    @server.call_tool()
    async def call_tool(name: str, **arguments) -> TextContent:
        if name in tool_handlers:
            handler = tool_handlers[name]["handler"]
            return await handler(**arguments)
        raise ValueError(f"Unknown tool: {name}")

    for tool_name, info in tool_handlers.items():
        server._tools[tool_name] = {
            "description": info["description"],
            "inputSchema": info["schema"]
        }

    return server

